# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl

# ---------------------------------------------------------------------------
# feature_dropout: inverted per-(batch, channel) dropout.
#   out[n, c, ...] = input[n, c, ...] * scale   if keep(n, c)  else 0
# with keep(n, c) = u(n, c) > p, one uniform draw per channel and
# scale = 1 / (1 - p).
#
# The reference materialises an (N, C) mask tensor and then applies it with a
# second kernel that recovers (n, c) with per-element integer division.  Here a
# single fused kernel does both: the channel index is the only random key and
# the tensor is addressed as (N*C, S) so no division is needed at all.
#
# Multiply precision is dtype matched to the device reference (verified on the
# target): fp16 evaluates x * fp16(scale) in fp16, bf16 and fp32 use fp32
# opmath with the fp32 scale.
# ---------------------------------------------------------------------------


@triton.jit
def _fd_uniform(idx, seed):
    """Portable counter-based uniform in [0, 1) (int32-safe, no philox)."""
    h = (idx ^ seed) * (-1640531527)  # 0x9E3779B1
    h = h ^ ((h >> 15) & 0x1FFFF)  # logical shift made sign-safe
    h = (h >> 8) & 0xFFFFFF  # 24 uniform bits
    return h.to(tl.float32) * 5.9604644775390625e-08  # 2**-24


@triton.jit(do_not_specialize=["numel", "thr", "scale", "seed"])
def _fd_flat_kernel(
    X,
    Y,
    numel,
    thr,
    scale,
    seed,
    EXACT: tl.constexpr,
    IS_FP16: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """S == 1: every element is its own channel.

    The keep decision is one integer multiply-add and a signed compare on 31
    hash bits. On this target `^` expands to or/and/not/and, so the previous
    xor-shift uniform plus int->float convert and float compare cost ~18 vector
    ops per block against a 2-op payload.  EXACT == True (numel % BLOCK == 0)
    compiles the block with no masks at all.
    """
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    h = offs * (-1640531527) + seed  # 0x9E3779B1, int32 wraparound
    keep = (h & 0x7FFFFFFF) >= thr  # 31 uniform bits; drop prob = thr / 2**31
    if EXACT:
        x = tl.load(X + offs)
        if IS_FP16:
            y = tl.where(keep, x * scale.to(tl.float16), tl.zeros([BLOCK], tl.float16))
        else:
            y = tl.where(keep, x.to(tl.float32) * scale, tl.zeros([BLOCK], tl.float32))
        tl.store(Y + offs, y)
    else:
        valid = offs < numel
        x = tl.load(X + offs, mask=valid, other=0.0)
        if IS_FP16:
            y = tl.where(keep, x * scale.to(tl.float16), tl.zeros([BLOCK], tl.float16))
        else:
            y = tl.where(keep, x.to(tl.float32) * scale, tl.zeros([BLOCK], tl.float32))
        tl.store(Y + offs, y, mask=valid)


@triton.jit(do_not_specialize=["NC", "p", "scale", "seed"])
def _fd_channel_kernel(
    X,
    Y,
    NC,
    p,
    scale,
    seed,
    S: tl.constexpr,
    BLOCK_C: tl.constexpr,
    BLOCK_S: tl.constexpr,
    EXACT: tl.constexpr,
    IS_FP16: tl.constexpr,
):
    """S > 1: one random value per (n, c) channel, shared by all S positions.

    The mask is computed once per channel (BLOCK_C values), never per element.
    S is a constexpr so the (BLOCK_C, BLOCK_S) tile has a static stride, and
    EXACT == True compiles a fully in-bounds tile with no masks at all (no
    set_mask_norm and no pad fill of the tile).
    """
    ch = tl.program_id(0) * BLOCK_C + tl.arange(0, BLOCK_C)
    s = tl.program_id(1) * BLOCK_S + tl.arange(0, BLOCK_S)

    u = _fd_uniform(ch, seed)
    mvec = tl.where(u > p, scale, 0.0)  # [BLOCK_C] fp32
    off = ch[:, None] * S + s[None, :]

    if EXACT:
        x = tl.load(X + off)
        if IS_FP16:
            y = x * mvec.to(tl.float16)[:, None]
        else:
            y = x.to(tl.float32) * mvec[:, None]
        tl.store(Y + off, y)
    else:
        valid = (ch < NC)[:, None] & (s < S)[None, :]
        x = tl.load(X + off, mask=valid, other=0.0)
        if IS_FP16:
            y = x * mvec.to(tl.float16)[:, None]
        else:
            y = x.to(tl.float32) * mvec[:, None]
        tl.store(Y + off, y, mask=valid)


@triton.jit(do_not_specialize=["numel"])
def _fd_copy_kernel(X, Y, numel, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    valid = offs < numel
    tl.store(Y + offs, tl.load(X + offs, mask=valid, other=0.0), mask=valid)


@triton.jit(do_not_specialize=["numel"])
def _fd_zero_kernel(Y, numel, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    valid = offs < numel
    tl.store(Y + offs, tl.zeros([BLOCK], dtype=tl.float32), mask=valid)


_SEED_STATE = [0x1F2E3D4C]


def _next_seed():
    v = _SEED_STATE[0] & 0x7FFFFFFF
    _SEED_STATE[0] = (v * 1103515245 + 12345) & 0x7FFFFFFF
    return v


def _pow2(n):
    return 1 << (n - 1).bit_length() if n > 1 else 1


def _flat_block(numel, is_fp16):
    if numel <= 8192:
        return 1024
    if not is_fp16:
        return 4096
    # fp16 keeps 8192-element blocks for every size above one program: the
    # medium [1024,1024] footprint is overhead-bound (540 GB/s on an L2-resident
    # 4 MB working set), so halving the program count helps, and the large cases
    # are DMA-bound. Only fp16 fits: 16384 overflows the 192 KB UB for every
    # dtype, and even 8192 overflows for bf16 (fp32 staging) and fp32.
    return 8192


def _fill(input, out, numel, zero=False):
    if numel == 0:
        return
    block = 4096
    grid = (triton.cdiv(numel, block),)
    if zero:
        _fd_zero_kernel[grid](out, numel, BLOCK=block)
    else:
        _fd_copy_kernel[grid](input, out, numel, BLOCK=block)


def _feature_dropout_out(input, out, p):
    """Dropout path: input.ndim >= 2 and 0 < p < 1. Writes into `out`."""
    N = input.shape[0]
    C = input.shape[1]
    NC = N * C
    numel = input.numel()
    if numel == 0:
        return out
    S = numel // NC
    scale = 1.0 / (1.0 - p)
    seed = _next_seed()
    is_fp16 = input.dtype == torch.float16

    if S == 1:
        block = _flat_block(numel, is_fp16)
        thr = int(p * 2147483648.0)
        _fd_flat_kernel[(triton.cdiv(numel, block),)](
            input,
            out,
            numel,
            thr,
            scale,
            seed,
            EXACT=(numel % block == 0),
            IS_FP16=is_fp16,
            BLOCK=block,
        )
    else:
        # One program covers a large, statically strided, fully in-bounds tile
        # so the per-program DMA/compute serialization is amortized over many
        # more elements than the 4096-element tiles of round 2. bf16 is the one
        # dtype that cannot take 16384: its fp32 staging buffer needs 197 KB of
        # the 192 KB UB (verified by preflight), so it keeps 8192.
        target = 8192 if input.dtype == torch.bfloat16 else 16384
        bs = S if S <= 2048 else 2048
        bc = max(1, target // bs)
        cap = _pow2(NC)
        if bc > cap:
            bc = cap
        exact = (NC % bc == 0) and (S % bs == 0)
        grid = (
            NC // bc if exact else triton.cdiv(NC, bc),
            S // bs if exact else triton.cdiv(S, bs),
        )
        _fd_channel_kernel[grid](
            input,
            out,
            NC,
            p,
            scale,
            seed,
            S=S,
            BLOCK_C=bc,
            BLOCK_S=bs,
            EXACT=exact,
            IS_FP16=is_fp16,
        )
    return out


def feature_dropout(input, p, train=True):
    if not isinstance(p, (int, float)):
        p = float(p)

    if not train or p == 0:
        out = torch.empty_like(input)
        _fill(input, out, input.numel(), zero=False)
        return out

    if p == 1:
        out = torch.empty_like(input)
        _fill(input, out, input.numel(), zero=True)
        return out

    if input.ndim < 2:
        raise RuntimeError(
            "Feature dropout requires at least 2 dimensions in the input"
        )

    assert 0.0 < p < 1.0, "p must be in (0, 1)"

    out = torch.empty_like(input)
    return _feature_dropout_out(input, out, p)


def feature_dropout_(input, p, train=True):
    """In-place variant: writes the result back into `input`."""
    if not isinstance(p, (int, float)):
        p = float(p)

    if not train or p == 0:
        return input

    if p == 1:
        _fill(input, input, input.numel(), zero=True)
        return input

    if input.ndim < 2:
        raise RuntimeError(
            "Feature dropout requires at least 2 dimensions in the input"
        )

    assert 0.0 < p < 1.0, "p must be in (0, 1)"
    return _feature_dropout_out(input, input, p)
